function createSMS() {
  const isEnglish = window.location.pathname.includes("main_en");
  const bankCode = document.getElementById("bank").value;
  const phoneNumber = document.getElementById("phone_number").value.replace(/-/g, "");
  const amount = document.getElementById("amount").value;
  const details = document.getElementById("details").value;

  if (!(bankCode && phoneNumber && amount && details)) {
    const message = isEnglish ? "Please complete all fields." : "Por favor completa todos los campos.";
    alert(message);
    return;
  }

  const message = `Pase ${amount} ${phoneNumber} ${details}`;
  const encodedMessage = encodeURIComponent(message);
  const isiOS = /iPhone|iPad|iPod/i.test(navigator.userAgent);

  const smsUrl = isiOS
    ? `sms:${bankCode}&body=${encodedMessage}`
    : `sms:${bankCode}?body=${encodedMessage}`;
    
  const tempLink = document.createElement('a');
  tempLink.href = smsUrl;
  tempLink.style.display = 'none';
  document.body.appendChild(tempLink);
  tempLink.click();
  document.body.removeChild(tempLink);
}